TLM.f("Sancti/09-24",{"officium":"Beatæ Mariæ Virginis de Mercede","rule":["ex C11;","Gloria","Prefatio=Maria=Festivitate"],"ruleInherited":["Gloria","Credo","Prefatio=Maria=Festivitate","Gloria","Suffr=Spiritu;Ecclesiæ,Papa;;","Prefatio=Maria=veneratione;"],"fallback":"Commune/C11","from":{"Introitus":"Commune/C11","Lectio":"Commune/C11","Graduale":"Commune/C11","GradualeP":"Commune/C11","Tractus":"Commune/C11","Evangelium":"Commune/C11","Offertorium":"Commune/C11","Communio":"Commune/C11"},"sections":{"Introitus":[{"k":"rubric","la":"Sedulius"},{"k":"text","la":"Salve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum."},{"k":"ref","la":"Ps 44:2"},{"k":"text","la":"Eructávit cor meum verbum bonum: dico ego ópera mea Regi."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Salve, sancta parens, eníxa puérpera Regem: qui cælum terrámque regit in sǽcula sæculórum."}],"Oratio":[{"k":"text","la":"Deus, qui per gloriosíssimam Fílii tui Matrem, ad liberandos Christi fidéles a potestáte paganórum, nova Ecclésiam tuam prole amplificáre dignátus es: præsta, quǽsumus; ut, quam pie venerámur tanti óperis institutrícem, ejus páriter méritis et intercessióne, a peccátis ómnibus et captivitáte dæmonis liberémur."},{"k":"macro","name":"Per eundem"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Eccli 24:14-16"},{"k":"text","la":"Ab inítio et ante sǽcula creáta sum, et usque ad futúrum sǽculum non désinam, et in habitatióne sancta coram ipso ministrávi. Et sic in Sion firmáta sum, et in civitáte sanctificáta simíliter requiévi, et in Jerúsalem potéstas mea. Et radicávi in pópulo honorificáto, et in parte Dei mei heréditas illíus, et in plenitúdine sanctórum deténtio mea."}],"Graduale":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénta es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo. Allelúja, allelúja.","mark":"V"},{"k":"text","la":"Post partum, Virgo, invioláta permansísti: Dei Génetrix, intercéde pro nobis. Allelúja.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis"},{"k":"ref","la":"Luke 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Benedícta et venerábilis es, Virgo María: quæ sine tactu pudóris invénia es Mater Salvatóris."},{"k":"text","la":"Virgo, Dei Génetrix, quem totus non capit orbis, in tua se clausit víscera factus homo.","mark":"V"},{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 11:27-28"},{"k":"text","la":"In illo témpore: Loquénte Jesu ad turbas, extóllens vocem quædam múlier de turba, dixit illi: Beátus venter, qui te portávit, et úbera, quæ suxísti. At ille dixit: Quinímmo beáti, qui áudiunt verbum Dei, et custódiunt illud."}],"Offertorium":[{"k":"ref","la":"Luc 1:28 1:42"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus, et benedíctus fructus ventris tui."}],"Secreta":[{"k":"text","la":"Tua, Dómine, propitiatióne, et beátæ Maríæ semper Vírginis intercessióne, ad perpétuam atque præséntem hæc oblátio nobis profíciat prosperitátem et pacem."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"text","la":"Beáta víscera Maríæ Vírginis, quæ portavérunt ætérni Patris Fílium."}],"Postcommunio":[{"k":"text","la":"Sumptis, Dómine, salútis nostræ subsídiis: da, quǽsumus, beátæ Maríæ semper Vírginis patrocíniis nos ubíque prótegi; in cujus veneratióne hæc tuæ obtúlimus majestáti."},{"k":"macro","name":"Per Dominum"}]},"hr":{"07601f859b330904":{"t":"<i>Pomolimo se</i>.\nBože, koji si se udostojao proširiti svoju Crkvu po slavnoj Majci Sina svoga novim potomstvom za oslobođenje kršćana iz poganske vlasti, daj, molimo, da se po zaslugama i zagovoru one koju pobožno slavimo kao utemeljiteljicu takva djela izbavimo od svih grijeha i od đavolskog ropstva.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"b5b1bdcbf7bad4ad":{"t":"Tvojim smilovanjem, Gospodine, i zagovorom blažene Marije, vazda Djevice, koristila nam ova žrtva za vječnu i sadašnju sreću i mir.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"91ad6f2bf907ac82":{"t":"<i>Pomolimo se</i>.\nPrimivši, Gospodine, okrepe našega spasenja, molimo te, da nas svuda štiti zagovor blažene Marije vazda Djevice kojoj smo na čast prinijeli ove žrtve tvojemu veličanstvu.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}},"variants":{"paschal":{"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Num 17:8"},{"k":"text","la":"Virga Jesse flóruit: Virgo Deum et hóminem génuit: pacem Deus réddidit, in se reconcílians ima summis."},{"k":"ref","la":"Luc 1:28"},{"k":"text","la":"Ave, María, grátia plena; Dóminus tecum: benedícta tu in muliéribus. Allelúja."}],"Tractus":[{"k":"text","la":"Gaude, María Virgo, cunctas hǽreses sola interemísti."},{"k":"text","la":"Quæ Gabriélis Archángeli dictis credidísti.","mark":"V"},{"k":"text","la":"Dum Virgo Deum et hóminem genuísti: et post partum, Virgo, invioláta permansísti.","mark":"V"},{"k":"text","la":"Dei Génetrix, intercéde pro nobis.","mark":"V"}]}}});
